    {
      "name": "Filter.eventually_cofinite",
      "module_name": "Mathlib.Order.Filter.Cofinite",
      "kind": "theorem",
      "type": "∀ {α : Type u_2} {p : α → Prop}, (∀ᶠ (x : α) in Filter.cofinite, p x) ↔ {x | ¬p x}.Finite"
    },
    {
      "name": "Filter.mem_cofinite",
      "module_name": "Mathlib.Order.Filter.Cofinite",
      "kind": "theorem",
      "type": "∀ {α : Type u_2} {s : Set α}, s ∈ Filter.cofinite ↔ sᶜ.Finite"
    },
    {
      "name": "Set.Finite.compl_mem_cofinite",
      "module_name": "Mathlib.Order.Filter.Cofinite",
      "kind": "theorem",
      "type": "∀ {α : Type u_2} {s : Set α}, s.Finite → sᶜ ∈ Filter.cofinite"
    },
    {
      "name": "Finset.eventually_cofinite_notMem",
      "module_name": "Mathlib.Order.Filter.Cofinite",
      "kind": "theorem",
      "type": "∀ {α : Type u_2} (s : Finset α), ∀ᶠ (x : α) in Filter.cofinite, x ∉ s"
    },
    {
      "name": "Set.Finite.eventually_cofinite_notMem",
      "module_name": "Mathlib.Order.Filter.Cofinite",
      "kind": "theorem",
      "type": "∀ {α : Type u_2} {s : Set α}, s.Finite → ∀ᶠ (x : α) in Filter.cofinite, x ∉ s"
    },
    {
      "name": "Filter.hasBasis_cofinite",
      "module_name": "Mathlib.Order.Filter.Cofinite",
      "kind": "theorem",
      "type": "∀ {α : Type u_2}, Filter.cofinite.HasBasis (fun s => s.Finite) compl"
    },
    {
      "name": "Filter.compl_mem_hyperfilter_of_finite",
      "module_name": "Mathlib.Order.Filter.Ultrafilter.Basic",
      "kind": "theorem",
      "type": "∀ {α : Type u} [inst : Infinite α] {s : Set α}, s.Finite → sᶜ ∈ Filter.hyperfilter α"
    },
    {
      "name": "Filter.mem_hyperfilter_of_finite_compl",
      "module_name": "Mathlib.Order.Filter.Ultrafilter.Basic",
      "kind": "theorem",
      "type": "∀ {α : Type u} [inst : Infinite α] {s : Set α}, sᶜ.Finite → s ∈ Filter.hyperfilter α"
    }
  ]
}
